head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vSchClsDd = '';
scwin.vRowCount = 0;
scwin.processGp;
scwin.vIsurCd, scwin.vBndClssCd, scwin.vBndInstCd;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name searchClsEnd
 * @description 국고채권마감완료 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchClsEnd = function() {
    let param = '';
    param += '&{P}V_CLS_DD=' + edt_ClsDd.getValue();
    let dsNm = 'BNS_CLS_TRESRYBND';
    let qryId = 'lds.stf.bnscls.select.listTresrybndClsEnd';
    $c.bns.fn_SearchBns("ULDBNS30000.xml", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name searchCls
 * @description 국고채권마감 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchCls = function() {
    let param = '';
    param += '&{P}V_GOVBND_FUT_TRNSM_TASK_DD=' + edt_ClsDd.getValue();
    // GOVBND_FUT_TRNSM_TASK_DD='+ getObjectValue(edt_ClsDd)
    let dsNm = 'BNS_CLS_TRESRYBND';
    // var qryId = 'lds.stf.bnscls.select.listTresrybndCls';
    let qryId = 'lds.stf.bnstresry.select.createTresrybndAsTaskDd.SendCfm';
    $c.bns.fn_SearchBns("ULDBNS30000.xml", dts_List, dsNm, qryId, param);
};

/**
 * @method
 * @name searchClsCheck
 * @description 국고채권마감체크 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.searchClsCheck = function() {
    let dsNm = 'BNS_CLS_TRESRYBND_CHK';
    let qryId = 'lds.stf.bnscls.select.readCheckTresrybndCls';
    $c.bns.fn_SearchBns("ULDBNS30000.xml", dts_Checker, dsNm, qryId, '');
};

/**
 * @method
 * @name clsProcs
 * @description 국고채 마감한다. (5년물에서 3년물로 수정 jackal_150127)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.clsProcs = async function() {
    let msg = '';
    let strtDd = dts_Checker.getCellData(1, 'STRT_DD');

    // 종목약명 20byte 초과  체크
    const param11 = '&{P}V_STRT_DD=' + dts_Checker.getCellData(1, 'STRT_DD');
    const dsNm11 = 'BNS_CLS_TRESRYBND_CHK';
    const qryId11 = 'lds.stf.bnscls.select.listCheckTresrybndCls.IsuAbbrvNm';
    $c.bns.fn_SearchBns("ULDBNS30000.xml", dts_CheckerBiz, dsNm11, qryId11, param11);
    if (dts_CheckerBiz.getRowCount() > 0) {
        const chk11 = dts_CheckerBiz.getCellData(1, 'CHK1_NEW');
        // if (chk11 != '' )
        // {
        //    msg = '- '+chk11+' 종목약명이 20 byte 을 초과했습니다.\n- 시스템관리자에게 문의하십시요.';
        //    alert(msg);
        //    return;
        // }
    }

    // 국채정보 송신 마감 스트립잔액 체크
    let param = '&{P}V_STRT_DD=' + strtDd;
    let dsNm = 'BNS_CLS_TRESRYBND_CHK';
    let qryId = 'lds.stf.bnscls.select.listCheckTresrybndClsStripAmt';
    $c.bns.fn_SearchBns("ULDBNS30000.xml", dts_CheckerBiz, dsNm, qryId, param);
    if (dts_CheckerBiz.getRowCount() > 0) {
        for (let i = 1; i <= dts_CheckerBiz.getRowCount(); i++) {
            msg += dts_CheckerBiz.getCellData(i, 'MSG_STRIP_CONT') + '\n';
        }
        msg = '- 스트립잔액이 존재할수없는 종목이 있습니다.\n' + msg;
        msg += '- 스트립잔액은 발행일이 2006년이후이며, 3년물에 해당됩니다.\n- 위 종목을 시스템관리자에게 문의하십시오.';
        await $c.win.alert(msg);
        return;
    }

    // 미처리업무 체크
    let param = '&{P}V_STRT_DD=' + dts_Checker.getCellData(1, 'STRT_DD');
    let dsNm = 'BNS_CLS_TRESRYBND_CHK';
    let qryId = 'lds.stf.bnscls.select.listCheckTresrybndNonProcBiz';
    $c.bns.fn_SearchBns("ULDBNS30000.xml", dts_CheckerBiz, dsNm, qryId, param);
    const chk1 = dts_CheckerBiz.getCellData(1, 'CHK1_NEW');
    const chk2 = dts_CheckerBiz.getCellData(1, 'CHK2_ADD');
    const chk3 = dts_CheckerBiz.getCellData(1, 'CHK3_REDMPT');
    if (chk1 !== '' || chk2 !== '' || chk3 !== '') {
        msg = '처리하지 않은 종목이 있습니다. \n신규상장 : ' + chk1 + '\n추가상장 : ' + chk2 + '\n중도상환 : ' + chk3 + '\n마감처리하시겠습니까?';
        if (!window.confirm(msg)) return;
    }

    // 마감체크
    scwin.processGp = '4';
    dts_Checker.SyncLoad = 'true';
    scwin.searchClsCheck();
    if (dts_Checker.getCellData(1, 'CLS_PROCS_YN') === 'Y') {
        await $c.win.alert('-이미 마감처리되었습니다.\n-재마감이 필요하면 시스템관리자에게 연락하십시오.');
        return;
    }
    // 전송내역확인 체크 추가 jackal_190109
    if (dts_Checker.getCellData(1, 'GOVBND_CFM_YN') === 'N') {
        await $c.win.alert('-국고채 전송내역확인 데이타가 없습니다.\n-전송내역확인 처리후 마감처리가 가능합니다.');
        return;
    }
    scwin.processGp = '1'; // 체크 후 원복

    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "국채마감"))) return;
    let url = "/bns/TresrybndCls.do?method=processCls";
    url += "&SCREN_ID=" + "ULDBNS30000.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    let param = "STRT_DD=" + strtDd;
    param += ',GOVBND_FUT_TRNSM_TASK_DD=' + edt_ClsDd.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name reClsProcs
 * @description 재마감처리 한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reClsProcs = async function() {
    scwin.processGp = '9';
    let strtDd = dts_Checker.getCellData(1, 'STRT_DD');

    // 채권마감이력 확인
    let msg = '';
    if (dts_Checker.getCellData(1, 'CLS_PROCS_YN') === 'Y') {
        msg += '채권송신(국고채선물)데이터를 다시 생성하여 송신 할 경우에 해당합니다.';
        msg += '\n다음데이타를 클리어한다.';
        msg += '\n- 국고채전송관리테이블 TBLD_B_GOVBND_FUT_TRNSM 오늘날짜 데이터 삭제, 초기화.';
        await $c.win.alert(msg);
    } else {
        msg += '업무마감이 되지 않아 업무마감처리를';
        msg += '\n다시 하실수 없습니다.';
        await $c.win.alert(msg);
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "재마감처리"))) return;
    let url = "/bns/TresrybndCls.do?method=reProcessCls";
    url += "&SCREN_ID=" + "ULDBNS30000.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    let param = "STRT_DD=" + strtDd;
    param += ',GOVBND_FUT_TRNSM_TASK_DD=' + edt_ClsDd.getValue();
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**
 * @method
 * @name processTresrybndSendCfm
 * @description 국고채 전송내역 송신할 데이타 생성한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.processTresrybndSendCfm = async function() {
    // 마감시 전송내역 생성 못하도록 함. jackal_190109
    if (dts_Checker.getCellData(1, 'CLS_PROCS_YN') === 'Y') {
        await $c.win.alert('국고채 업무마감 작업이 이미 종료되었습니다.\n국고채 업무마감 이후에는 전송내역확인 처리를 하실수 없습니다.');
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "국고채 전송내역확인"))) return;
    let url = "/bns/TresrybndCls.do?method=processTresrybndSendCfm";
    url += "&SCREN_ID=" + "ULDBNS30000.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    let strtDd = dts_Checker.getCellData(1, 'STRT_DD');
    let param = "STRT_DD=" + strtDd;
    // var param = 'REG_YN='+ vRegYn;
    param += ',GOVBND_FUT_TRNSM_TASK_DD=' + edt_ClsDd.getValue();
    // getObjectValue(edt_ClsDd);

    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Temp)";
    trs_Save.Parameters = param;
    trs_Save.Post();
};

/**********************************************
 * 함수명   : fn_SearchMktact
 * 설명       : 마감전 전송내역 시장조치내역 조회한다.
 ***********************************************/
scwin.vStdCd;

/**
 * @method
 * @name searchMktact
 * @description search Mktact 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchMktact = function() {
    let strtDd = dts_Checker.getCellData(1, 'STRT_DD');
    let param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + strtDd;
    param += "&{P}V_APPL_YN=N";
    // param += "&{P}V_STD_CD=KR6015861S58";

    let dsNm = 'BNS_MKTACT_DTL';
    let qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    $c.bns.fn_SearchBns("ULDBNS30000.xml", dts_MktDetail, dsNm, qryId, param);
};

/**********************************************
 * 함수명   : fn_SearchMktact1
 * 설명       : 마감내역 조회한다.
 ***********************************************/
scwin.vClsApplyYn;
scwin.vStrtDd;

/**
 * @method
 * @name searchMktact1
 * @description search Mktact1 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchMktact1 = function() {
    let param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + scwin.vStrtDd; // dts_CheckCls.NameValue(1, 'END_CLS_DD');
    // param += "&{P}V_STD_CD=KR6015861S58";

    let dsNm = 'BNS_MKTACT_DTL';
    let qryId = 'lds.stf.bnscommon.select.listMktactDtlMulty';
    if (scwin.vClsApplyYn === 'Y') param += "&{P}V_APPL_YN=Y";

    else param += "&{P}V_APPL_YN=N";
    $c.bns.fn_SearchBns("ULDBNS30000.xml", dts_MktDetail, dsNm, qryId, param);
};

/**
 * @method
 * @name gform_onload
 * @description 숨기기
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    // 숨기기
    btn_Search.hide();
    btn_ReClsProcs.hide();
    if (js_usr_tp_cd === '1') {
        // 운영자이면
        btn_ReClsProcs.show("");
    }
    img_ClsDd.hide();
    lbl_SendTm.hide();
    txb_SendTm.hide();

    // 패널라운드처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    $c.bns.BnsPanelToGroupBox(pnl_Item);

    // 마감체크조회
    scwin.processGp = '1';
    scwin.searchClsCheck();

    // 임시설정

    // dts_Temp.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_Temp.insertRow();
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    scwin.processGp = '2';
    scwin.vSchClsDd = edt_ClsDd.getValue();
    scwin.searchClsEnd();
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    if (rowcount > 0 && scwin.processGp === '2') {
        txb_UseNm.setValue(dts_List.getCellData(1, 'USR_NM'));
        txb_TaskTm.setValue(dts_List.getCellData(1, 'TASK_TM'));
        txb_ClsProcsYn.setValue(dts_List.getCellData(1, 'CLS_PROCS_YN'));
        txb_SendTm.setValue(dts_List.getCellData(1, 'SND_CLS_TM'));
        // jackal_190108 ftp 전송시간으로 변경
        // setObjectValue(txb_SendTm, dts_List.NameValue(1, 'TASK_TM'));//FTP전송방식변경후 송신마감시간은 의미없음 -> 작업시간으로 변경

    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    scwin.processGp = '1';
    scwin.searchClsCheck();
    scwin.searchCls();
};

/**
 * @method
 * @name img_ClsDd_onclick
 * @description img_ClsDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ClsDd_onclick = function() {
    popUpCalendar2(edt_ClsDd);
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    if (dts_List.getRowCount() === 0) return;
    // doLogSave(vScrenID, SCREN_PROCS_TP_CD_07, '');
    const fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_국고(이표)채정보송신마감.xls";
    $c.data.downloadGridViewExcel(grd_List, {fileName: "국고(이표)채정보송신마감", type: 8});
};

/**
 * @method
 * @name btn_ClsProcs_onclick
 * @description 「마감처리」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ClsProcs_onclick = async function() {
    await scwin.clsProcs();
};

/**
 * @method
 * @name dts_Checker_OnLoadCompleted
 * @description dts_Checker 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Checker_OnLoadCompleted = function(rowcount) {
    if (scwin.processGp === '4') return;
    edt_ClsDd.setValue(dts_Checker.getCellData(1, "CUR_DD"));
    txb_ClsProcsYn.setValue(dts_Checker.getCellData(1, "CLS_PROCS_YN"));
    txb_UseNm.setValue(dts_Checker.getCellData(1, "USR_NM"));
    txb_TaskTm.setValue(dts_Checker.getCellData(1, "TASK_TM"));
    if (txb_ClsProcsYn.getValue() === 'Y') {
        btn_ClsProcs.setBackgroundImage("../img/btn_ClsPrc_d.gif");
        btn_ClsProcs.setDisabled(true);
    }
    scwin.searchCls();
};

/**
 * @method
 * @name tab_List_OnSelChanged
 * @description tab List On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.tab_List_OnSelChanged = function(nIndex) {
    dts_List.removeAll();
    scwin.processGp = nIndex;
    txb_ClsProcsYn.setValue('');
    txb_UseNm.setValue('');
    txb_TaskTm.setValue('');
    txb_SendTm.setValue('');
    if (scwin.processGp === '1') {
        lbl_SendTm.hide();
        txb_SendTm.hide();
        btn_ClsProcs.show("");
        btn_Search.hide();
        img_ClsDd.hide();
        edt_ClsDd.setDisabled(true);
        scwin.searchClsCheck();
        btn_TresrybndClsIns.show("");
    } else {
        lbl_SendTm.show("");
        txb_SendTm.show("");
        if (scwin.vSchClsDd !== '') {
            edt_ClsDd.setValue(scwin.vSchClsDd);
        }
        btn_ClsProcs.hide();
        btn_Search.show("");
        img_ClsDd.show("");
        edt_ClsDd.setDisabled(false);
        btn_TresrybndClsIns.hide();
    }
};

/**
 * @method
 * @name btn_ReClsProcs_onclick
 * @description 「재마감처리」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ReClsProcs_onclick = async function() {
    await scwin.reClsProcs();
};

/**
 * @method
 * @name btn_TresrybndClsIns_onclick
 * @description 「전송내역확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_TresrybndClsIns_onclick = async function() {
    await scwin.processTresrybndSendCfm();
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_OnClick = function(row, colid) {
    if (row === 0) return;
    if (scwin.processGp === '1') // 전송내역 이면

    {
        dts_MktDetail.removeAll();
        // if(dts_SendInfo.NameValue(row, 'MULTY_YN') != 'Y') return;

        scwin.vStdCd = dts_List.getCellData(row, 'STD_CD');
        scwin.searchMktact();
        // fn_SearchClsDd('');

    } else if (scwin.processGp === '2') //  마감내역 이면

    {
        dts_MktDetail.removeAll();
        scwin.vStdCd = dts_List.getCellData(row, 'STD_CD');
        scwin.vClsApplyYn = dts_List.getCellData(row, 'CLS_APPLY_YN');
        scwin.vStrtDd = dts_List.getCellData(row, 'STRT_DD');
        scwin.searchMktact1();
    }

    // alert('grd_List.OnClick('+row+','+ colid+')');

};
